import { v7 } from 'uuid'

/**
 * Primary keys are UUID v7: generated by the application, sortable by creation
 * time (so B-tree indexes stay dense) and opaque to the outside world.
 *
 * Generating them here rather than in Postgres lets the ingestion build a whole
 * object graph — a race, its entries, their laps — in one pure pass, without a
 * round trip per row to read back a server-side default.
 */
export type Id = string

export type IdFactory = () => Id

export const newId: IdFactory = v7
